"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7583],{32934:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponEffectsController","desc":"Receives replicated combat-FX packets and renders them through `CombatVfx`:\\n- `WeaponFired`: other players\' shots get muzzle flash (once per shooter per\\n  frame) + tracer + impact; a ricochet (shooter = a player\'s character) gets\\n  tracer + impact; any other shooter is an enemy and gets only the impact\\n  (its flash and streak come from `EnemyFired`). The local player\'s own\\n  shots are drawn in GunHandler.\\n- `EnemyFired`: enemy muzzle flash + a streak that flies at bullet speed.\\n- `ExplosionAt`: explosion burst + scorch decal, for every source.\\nAlso renders the Weak Spot glow (`EnemyMarked`).","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponEffectsController.client.luau"}}')}}]);